def _term_base(term: str) -> str:
    t = re.sub(r"（.+?）", "", term).strip()
    return re.sub(r"\s+[A-Za-z][A-Za-z0-9+/.-]*$", "", t).strip()


def clean_def_block(text: str) -> str:
    main_terms: set[str] = set()
    for ln in text.splitlines():
        m0 = re.match(r"^- \*\*(.+?)\*\*[：:]", ln.strip())
        if m0 and "（作用）" not in m0.group(1):
            main_terms.add(_term_base(m0.group(1)))
    lines: list[str] = []
    seen: set[str] = set()
    for ln in text.splitlines():
        s = ln.strip()
        if not s.startswith("- "):
            continue
        if "（答卷·必背）" in s and "**" not in s:
            continue
        s = s.replace("用于主要用于", "主要用于").replace("用于用于", "用于")
        s = re.sub(r"(\*\*作用\*\*[：:])用于([^。；\n]{0,12}?用于)", r"\1\2", s)
        m_dup = re.match(r"^- \*\*(.+?)（作用）\*\*[：:]", s)
        if m_dup and _term_base(m_dup.group(1)) in main_terms:
            continue
        plain = re.sub(r"\*\*", "", s)
        if plain in seen:
            continue
        key = re.sub(r"\*\*", "", s.split("：", 1)[0].split(":", 1)[0]).strip()
        if key in seen:
            continue
        seen.add(key)
        seen.add(plain)
        m = re.match(r"^-\s*(.+?)（答卷·定义）[：:]\s*(.+)$", s)
        if m:
            lines.append(
                r.polish_def_act_line(f"- **{m.group(1).strip()}**：{m.group(2).strip()}")
            )
            continue
        m2 = re.match(r"^-\s*(.+?)（答卷·作用）\*\*[：:]\s*(.+)$", s)
        if m2:
            lines.append(
                f"- **{m2.group(1).strip()}（作用）**：{m2.group(2).strip()}"
            )
            continue
        if "**" in s:
            lines.append(r.polish_def_act_line(s))
        else:
            lines.append(s)
        if len(lines) >= 14:
            break
    return r.clean_definition_output("\n".join(lines))


def main() -> None:
    base = json.loads(OV_PATH.read_text(encoding="utf-8"))
    base.update(MANUAL_PATCH)
    items = boot.load_items()
    slices = r.assign_slices(items)
    out = dict(base)
    for it in items:
        pid = it["id"]
        if pid in r.SKIP_IDS or pid.startswith("kp-论文专题") or pid == "kp-内容":
            continue
        if pid in MANUAL_PATCH:
            out[pid] = clean_def_block(MANUAL_PATCH[pid])
            continue
        ch_text = ""
        ch_num = None
        if it.get("chapter"):
            ch_num = int(it["chapter"])
            cf = r.find_chapter_file(ch_num)
            if cf:
                ch_text = cf.read_text(encoding="utf-8")
        raw = boot.build_raw(it, items, slices)
        if not raw.strip():
            if pid in base and r.definition_text_len(base[pid]) >= MIN_LEN:
                out[pid] = clean_def_block(base[pid])
            continue
        title = it.get("title", "")
        keys = r.title_keywords(title)
        oref = it.get("outlineRef")
        defs = r.finalize_definitions(pid, raw, title, keys, ch_text, ch_num, oref)
        defs = clean_def_block(defs)
        if r.definition_text_len(defs) < MIN_LEN:
            if pid in base:
                out[pid] = clean_def_block(base[pid])
            continue
        if not r._def_has_what(defs) or not re.search(r"(作用|用于|主要用于)", defs):
            if pid in base:
                out[pid] = clean_def_block(base[pid])
            continue
        prev = clean_def_block(out.get(pid, base.get(pid, "")))
        if prev and r.definition_text_len(prev) > r.definition_text_len(defs) + 60:
            out[pid] = clean_def_block(r.merge_definition_lines(prev, defs, limit=14))
        else:
            out[pid] = defs
    OV_PATH.write_text(
        json.dumps(dict(sorted(out.items())), ensure_ascii=False, indent=2) + "\n",
        encoding="utf-8",
    )
    print({"overrides": len(out)})


if __name__ == "__main__":
    main()
